
`include "video_define.v"
module color_bar(
	input                 clk,           //pixel clock
	input                 rst,           //reset signal high active
	output                hs,            //horizontal synchronization
	output                vs,            //vertical synchronization
	output                de,            //video valid
	output[7:0]           rgb_r,         //video red data
	output[7:0]           rgb_g,         //video green data
	output[7:0]           rgb_b          //video blue data
);
//video timing parameter definition
`ifdef  VIDEO_1280_720
parameter H_ACTIVE = 16'd1280;           //horizontal active time (pixels)
parameter H_FP = 16'd110;                //horizontal front porch (pixels)
parameter H_SYNC = 16'd40;               //horizontal sync time(pixels)
parameter H_BP = 16'd220;                //horizontal back porch (pixels)
parameter V_ACTIVE = 16'd720;            //vertical active Time (lines)
parameter V_FP  = 16'd5;                 //vertical front porch (lines)
parameter V_SYNC  = 16'd5;               //vertical sync time (lines)
parameter V_BP  = 16'd20;                //vertical back porch (lines)
parameter HS_POL = 1'b1;                 //horizontal sync polarity, 1 : POSITIVE,0 : NEGATIVE;
parameter VS_POL = 1'b1;                 //vertical sync polarity, 1 : POSITIVE,0 : NEGATIVE;
`endif

//480x272 9Mhz
`ifdef  VIDEO_480_272
parameter H_ACTIVE = 16'd480; 
parameter H_FP = 16'd2;       
parameter H_SYNC = 16'd41;    
parameter H_BP = 16'd2;       
parameter V_ACTIVE = 16'd272; 
parameter V_FP  = 16'd2;     
parameter V_SYNC  = 16'd10;   
parameter V_BP  = 16'd2;     
parameter HS_POL = 1'b0;
parameter VS_POL = 1'b0;
`endif

//640x480 25.175Mhz
`ifdef  VIDEO_640_480
parameter H_ACTIVE = 16'd640; 
parameter H_FP = 16'd16;      
parameter H_SYNC = 16'd96;    
parameter H_BP = 16'd48;      
parameter V_ACTIVE = 16'd480; 
parameter V_FP  = 16'd10;    
parameter V_SYNC  = 16'd2;    
parameter V_BP  = 16'd33;    
parameter HS_POL = 1'b0;
parameter VS_POL = 1'b0;
`endif

//800x480 33Mhz
`ifdef  VIDEO_800_480
parameter H_ACTIVE = 16'd800; 
parameter H_FP = 16'd40;      
parameter H_SYNC = 16'd128;   
parameter H_BP = 16'd88;      
parameter V_ACTIVE = 16'd480; 
parameter V_FP  = 16'd1;     
parameter V_SYNC  = 16'd3;    
parameter V_BP  = 16'd21;    
parameter HS_POL = 1'b0;
parameter VS_POL = 1'b0;
`endif

//800x600 40Mhz
`ifdef  VIDEO_800_600
parameter H_ACTIVE = 16'd800; 
parameter H_FP = 16'd40;      
parameter H_SYNC = 16'd128;   
parameter H_BP = 16'd88;      
parameter V_ACTIVE = 16'd600; 
parameter V_FP  = 16'd1;     
parameter V_SYNC  = 16'd4;    
parameter V_BP  = 16'd23;    
parameter HS_POL = 1'b1;
parameter VS_POL = 1'b1;
`endif

//1024x768 65Mhz
`ifdef  VIDEO_1024_768
parameter H_ACTIVE = 16'd1024;
parameter H_FP = 16'd24;      
parameter H_SYNC = 16'd136;   
parameter H_BP = 16'd160;     
parameter V_ACTIVE = 16'd768; 
parameter V_FP  = 16'd3;      
parameter V_SYNC  = 16'd6;    
parameter V_BP  = 16'd29;     
parameter HS_POL = 1'b0;
parameter VS_POL = 1'b0;
`endif

//1920x1080 148.5Mhz
`ifdef  VIDEO_1920_1080
parameter H_ACTIVE = 16'd1920;
parameter H_FP = 16'd88;
parameter H_SYNC = 16'd44;
parameter H_BP = 16'd148; 
parameter V_ACTIVE = 16'd1080;
parameter V_FP  = 16'd4;
parameter V_SYNC  = 16'd5;
parameter V_BP  = 16'd36;
parameter HS_POL = 1'b1;
parameter VS_POL = 1'b1;
`endif
parameter H_TOTAL = H_ACTIVE + H_FP + H_SYNC + H_BP;//horizontal total time (pixels)
parameter V_TOTAL = V_ACTIVE + V_FP + V_SYNC + V_BP;//vertical total time (lines)
//define the RGB values for 8 colors
parameter WHITE_R       = 8'hff;
parameter WHITE_G       = 8'hff;
parameter WHITE_B       = 8'hff;
parameter YELLOW_R      = 8'hff;
parameter YELLOW_G      = 8'hff;
parameter YELLOW_B      = 8'h00;                                
parameter CYAN_R        = 8'h00;
parameter CYAN_G        = 8'hff;
parameter CYAN_B        = 8'hff;                                
parameter GREEN_R       = 8'h00;
parameter GREEN_G       = 8'hff;
parameter GREEN_B       = 8'h00;
parameter MAGENTA_R     = 8'hff;
parameter MAGENTA_G     = 8'h00;
parameter MAGENTA_B     = 8'hff;
parameter RED_R         = 8'hff;
parameter RED_G         = 8'h00;
parameter RED_B         = 8'h00;
parameter BLUE_R        = 8'h00;
parameter BLUE_G        = 8'h00;
parameter BLUE_B        = 8'hff;
parameter BLACK_R       = 8'h00;
parameter BLACK_G       = 8'h00;
parameter BLACK_B       = 8'h00;
reg hs_reg;                      //horizontal sync register
reg vs_reg;                      //vertical sync register
reg hs_reg_d0;                   //delay 1 clock of 'hs_reg'
reg vs_reg_d0;                   //delay 1 clock of 'vs_reg'
reg[11:0] h_cnt;                 //horizontal counter
reg[11:0] v_cnt;                 //vertical counter
reg[11:0] active_x;              //video x position 
reg[11:0] active_y;              //video y position 
reg[7:0] rgb_r_reg;              //video red data register
reg[7:0] rgb_g_reg;              //video green data register
reg[7:0] rgb_b_reg;              //video blue data register
reg h_active;                    //horizontal video active
reg v_active;                    //vertical video active
wire video_active;               //video active(horizontal active and vertical active)
reg video_active_d0;             //delay 1 clock of video_active
assign hs = hs_reg_d0;
assign vs = vs_reg_d0;
assign video_active = h_active & v_active;
assign de = video_active_d0;
assign rgb_r = rgb_r_reg;
assign rgb_g = rgb_g_reg;
assign rgb_b = rgb_b_reg;
always@(posedge clk or posedge rst)
begin
	if(rst == 1'b1)
		begin
			hs_reg_d0 <= 1'b0;
			vs_reg_d0 <= 1'b0;
			video_active_d0 <= 1'b0;
		end
	else
		begin
			hs_reg_d0 <= hs_reg;
			vs_reg_d0 <= vs_reg;
			video_active_d0 <= video_active;
		end
end

always@(posedge clk or posedge rst)
begin
	if(rst == 1'b1)
		h_cnt <= 12'd0;
	else if(h_cnt == H_TOTAL - 1)//horizontal counter maximum value
		h_cnt <= 12'd0;
	else
		h_cnt <= h_cnt + 12'd1;
end

always@(posedge clk or posedge rst)
begin
	if(rst == 1'b1)
		active_x <= 12'd0;
	else if(h_cnt >= H_FP + H_SYNC + H_BP - 1)//horizontal video active
		active_x <= h_cnt - (H_FP[11:0] + H_SYNC[11:0] + H_BP[11:0] - 12'd1);
	else
		active_x <= active_x;
end

always@(posedge clk or posedge rst)
begin
	if(rst == 1'b1)
		v_cnt <= 12'd0;
	else if(h_cnt == H_FP  - 1)//horizontal sync time
		if(v_cnt == V_TOTAL - 1)//vertical counter maximum value
			v_cnt <= 12'd0;
		else
			v_cnt <= v_cnt + 12'd1;
	else
		v_cnt <= v_cnt;
end

always@(posedge clk or posedge rst)
begin
	if(rst == 1'b1)
		hs_reg <= 1'b0;
	else if(h_cnt == H_FP - 1)//horizontal sync begin
		hs_reg <= HS_POL;
	else if(h_cnt == H_FP + H_SYNC - 1)//horizontal sync end
		hs_reg <= ~hs_reg;
	else
		hs_reg <= hs_reg;
end

always@(posedge clk or posedge rst)
begin
	if(rst == 1'b1)
		h_active <= 1'b0;
	else if(h_cnt == H_FP + H_SYNC + H_BP - 1)//horizontal active begin
		h_active <= 1'b1;
	else if(h_cnt == H_TOTAL - 1)//horizontal active end
		h_active <= 1'b0;
	else
		h_active <= h_active;
end

always@(posedge clk or posedge rst)
begin
	if(rst == 1'b1)
		vs_reg <= 1'd0;
	else if((v_cnt == V_FP - 1) && (h_cnt == H_FP - 1))//vertical sync begin
		vs_reg <= HS_POL;
	else if((v_cnt == V_FP + V_SYNC - 1) && (h_cnt == H_FP - 1))//vertical sync end
		vs_reg <= ~vs_reg;  
	else
		vs_reg <= vs_reg;
end

always@(posedge clk or posedge rst)
begin
	if(rst == 1'b1)
		v_active <= 1'd0;
	else if((v_cnt == V_FP + V_SYNC + V_BP - 1) && (h_cnt == H_FP - 1))//vertical active begin
		v_active <= 1'b1;
	else if((v_cnt == V_TOTAL - 1) && (h_cnt == H_FP - 1)) //vertical active end
		v_active <= 1'b0;   
	else
		v_active <= v_active;
end

always@(posedge clk or posedge rst)
begin
	if(rst == 1'b1)
		begin
			rgb_r_reg <= 8'h00;
			rgb_g_reg <= 8'h00;
			rgb_b_reg <= 8'h00;
		end
	else if(video_active)
		if(active_x == 12'd0)
			begin
				rgb_r_reg <= WHITE_R;
				rgb_g_reg <= WHITE_G;
				rgb_b_reg <= WHITE_B;
			end
		else if(active_x == (H_ACTIVE/8) * 1)
			begin
				rgb_r_reg <= YELLOW_R;
				rgb_g_reg <= YELLOW_G;
				rgb_b_reg <= YELLOW_B;
			end         
		else if(active_x == (H_ACTIVE/8) * 2)
			begin
				rgb_r_reg <= CYAN_R;
				rgb_g_reg <= CYAN_G;
				rgb_b_reg <= CYAN_B;
			end
		else if(active_x == (H_ACTIVE/8) * 3)
			begin
				rgb_r_reg <= GREEN_R;
				rgb_g_reg <= GREEN_G;
				rgb_b_reg <= GREEN_B;
			end
		else if(active_x == (H_ACTIVE/8) * 4)
			begin
				rgb_r_reg <= MAGENTA_R;
				rgb_g_reg <= MAGENTA_G;
				rgb_b_reg <= MAGENTA_B;
			end
		else if(active_x == (H_ACTIVE/8) * 5)
			begin
				rgb_r_reg <= RED_R;
				rgb_g_reg <= RED_G;
				rgb_b_reg <= RED_B;
			end
		else if(active_x == (H_ACTIVE/8) * 6)
			begin
				rgb_r_reg <= BLUE_R;
				rgb_g_reg <= BLUE_G;
				rgb_b_reg <= BLUE_B;
			end 
		else if(active_x == (H_ACTIVE/8) * 7)
			begin
				rgb_r_reg <= BLACK_R;
				rgb_g_reg <= BLACK_G;
				rgb_b_reg <= BLACK_B;
			end
		else
			begin
				rgb_r_reg <= rgb_r_reg;
				rgb_g_reg <= rgb_g_reg;
				rgb_b_reg <= rgb_b_reg;
			end         
	else
		begin
			rgb_r_reg <= 8'h00;
			rgb_g_reg <= 8'h00;
			rgb_b_reg <= 8'h00;
		end
end

endmodule 

// ROM-backed 640x480 startup/status layer. No TF, SDRAM or audio transactions.
// All RGB and timing outputs have exactly two pixel-clock latency.
module startup_status_screen #(
    parameter CURRENT_VIDEO = 1'b0
)(
    input wire clk,
    input wire rst,
    input wire vs,
    input wire de,
    input wire [23:0] source_rgb,
    input wire media_ready,
    input wire switch_pending,
    input wire [3:0] source_state,
    output reg out_vs,
    output reg out_de,
    output reg [23:0] out_rgb
);
reg previous_vs, previous_de;
reg [9:0] pixel_x, pixel_y;
reg [1:0] switch_sync;
reg [1:0] frame_mode;
reg [3:0] frame_state;
reg [5:0] animation_frame;
wire frame_start = previous_vs && !vs;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        previous_vs <= 1'b1;
        previous_de <= 1'b0;
        pixel_x <= 10'd0;
        pixel_y <= 10'd0;
        switch_sync <= 2'd0;
        frame_mode <= 2'd1;
        frame_state <= 4'd0;
        animation_frame <= 6'd0;
    end else begin
        previous_vs <= vs;
        previous_de <= de;
        switch_sync <= {switch_sync[0], switch_pending};
        if (!de) pixel_x <= 10'd0;
        else pixel_x <= pixel_x + 1'b1;
        if (frame_start) begin
            pixel_y <= 10'd0;
            // Only change screens in vertical blanking, never halfway down a frame.
            if (switch_sync[1]) frame_mode <= CURRENT_VIDEO ? 2'd3 : 2'd2;
            else if (!media_ready) frame_mode <= 2'd1;
            else frame_mode <= 2'd0;
            frame_state <= source_state;
            animation_frame <= (animation_frame == 6'd59) ? 6'd0 : animation_frame + 1'b1;
        end else if (previous_de && !de) pixel_y <= pixel_y + 1'b1;
    end
end

// Official logo source SHA256: 2803de9d379416c0f89fd2eba8cd1b0e56bead7431258d99137aef6af7e2967f
// 512x128 native logo, 32px native main glyphs, 16px footer; 4x4 shared tiles.
(* rom_style = "block" *) reg [8:0] logo_map [0:4095];
localparam [36863:0] logo_map_INIT = 36864';
integer logo_map_i;
initial begin
    for (logo_map_i=0; logo_map_i<4096; logo_map_i=logo_map_i+1)
        logo_map[logo_map_i] = logo_map_INIT[logo_map_i*9 +: 9];
end
(* rom_style = "block" *) reg [47:0] logo_tiles [0:511];
localparam [24575:0] logo_tiles_INIT = 24576';
integer logo_tiles_i;
initial begin
    for (logo_tiles_i=0; logo_tiles_i<512; logo_tiles_i=logo_tiles_i+1)
        logo_tiles[logo_tiles_i] = logo_tiles_INIT[logo_tiles_i*48 +: 48];
end
(* rom_style = "block" *) reg [7:0] font_map_lo [0:2047];
localparam [16383:0] font_map_lo_INIT = 16384';
integer font_map_lo_i;
initial begin
    for (font_map_lo_i=0; font_map_lo_i<2048; font_map_lo_i=font_map_lo_i+1)
        font_map_lo[font_map_lo_i] = font_map_lo_INIT[font_map_lo_i*8 +: 8];
end
(* rom_style = "block" *) reg [1:0] font_map_hi [0:2047];
localparam [4095:0] font_map_hi_INIT = 4096';
integer font_map_hi_i;
initial begin
    for (font_map_hi_i=0; font_map_hi_i<2048; font_map_hi_i=font_map_hi_i+1)
        font_map_hi[font_map_hi_i] = font_map_hi_INIT[font_map_hi_i*2 +: 2];
end
(* rom_style = "block" *) reg [31:0] font_tiles [0:1023];
localparam [32767:0] font_tiles_INIT = 32768';
integer font_tiles_i;
initial begin
    for (font_tiles_i=0; font_tiles_i<1024; font_tiles_i=font_tiles_i+1)
        font_tiles[font_tiles_i] = font_tiles_INIT[font_tiles_i*32 +: 32];
end
function [5:0] text_glyph;
    input [2:0] line_id;
    input [4:0] column;
    begin
        case ({line_id, column})
            8'd0: text_glyph = 6'd1;
            8'd1: text_glyph = 6'd2;
            8'd2: text_glyph = 6'd3;
            8'd3: text_glyph = 6'd4;
            8'd32: text_glyph = 6'd5;
            8'd33: text_glyph = 6'd6;
            8'd34: text_glyph = 6'd7;
            8'd35: text_glyph = 6'd8;
            8'd36: text_glyph = 6'd9;
            8'd37: text_glyph = 6'd10;
            8'd38: text_glyph = 6'd11;
            8'd39: text_glyph = 6'd11;
            8'd40: text_glyph = 6'd11;
            8'd64: text_glyph = 6'd5;
            8'd65: text_glyph = 6'd6;
            8'd66: text_glyph = 6'd12;
            8'd67: text_glyph = 6'd13;
            8'd68: text_glyph = 6'd14;
            8'd69: text_glyph = 6'd15;
            8'd70: text_glyph = 6'd16;
            8'd71: text_glyph = 6'd17;
            8'd72: text_glyph = 6'd18;
            8'd73: text_glyph = 6'd11;
            8'd74: text_glyph = 6'd11;
            8'd75: text_glyph = 6'd11;
            8'd96: text_glyph = 6'd5;
            8'd97: text_glyph = 6'd6;
            8'd98: text_glyph = 6'd12;
            8'd99: text_glyph = 6'd13;
            8'd100: text_glyph = 6'd14;
            8'd101: text_glyph = 6'd19;
            8'd102: text_glyph = 6'd20;
            8'd103: text_glyph = 6'd17;
            8'd104: text_glyph = 6'd18;
            8'd105: text_glyph = 6'd11;
            8'd106: text_glyph = 6'd11;
            8'd107: text_glyph = 6'd11;
            8'd128: text_glyph = 6'd21;
            8'd129: text_glyph = 6'd22;
            8'd130: text_glyph = 6'd0;
            8'd131: text_glyph = 6'd23;
            8'd132: text_glyph = 6'd24;
            8'd133: text_glyph = 6'd25;
            8'd134: text_glyph = 6'd26;
            8'd135: text_glyph = 6'd0;
            8'd136: text_glyph = 6'd27;
            8'd137: text_glyph = 6'd28;
            default: text_glyph = 6'd0;
        endcase
    end
endfunction
function [5:0] hexadecimal_glyph;
    input [3:0] state;
    begin
        case (state)
            4'd0: hexadecimal_glyph = 6'd29;
            4'd1: hexadecimal_glyph = 6'd30;
            4'd2: hexadecimal_glyph = 6'd31;
            4'd3: hexadecimal_glyph = 6'd32;
            4'd4: hexadecimal_glyph = 6'd33;
            4'd5: hexadecimal_glyph = 6'd34;
            4'd6: hexadecimal_glyph = 6'd35;
            4'd7: hexadecimal_glyph = 6'd36;
            4'd8: hexadecimal_glyph = 6'd37;
            4'd9: hexadecimal_glyph = 6'd38;
            4'd10: hexadecimal_glyph = 6'd39;
            4'd11: hexadecimal_glyph = 6'd40;
            4'd12: hexadecimal_glyph = 6'd41;
            4'd13: hexadecimal_glyph = 6'd42;
            4'd14: hexadecimal_glyph = 6'd43;
            4'd15: hexadecimal_glyph = 6'd22;
            default: hexadecimal_glyph = 6'd0;
        endcase
    end
endfunction

reg [2:0] text_line;
reg [4:0] text_column;
reg [4:0] glyph_row, glyph_bit;
reg text_enable;
reg [9:0] text_x_offset;
reg [9:0] status_x;
reg [4:0] status_length;
reg [5:0] selected_glyph;
reg [4:0] footer_glyph;
reg [10:0] font_address;
wire logo_region = de && (pixel_x >= 10'd64) && (pixel_x < 10'd576) &&
                   (pixel_y >= 10'd122) && (pixel_y < 10'd250);
wire [8:0] logo_x_offset = pixel_x - 10'd64;
wire [6:0] logo_y_offset = pixel_y - 10'd122;
wire [11:0] logo_address = {logo_y_offset[6:2], logo_x_offset[8:2]};
wire [1:0] dot_count = (animation_frame < 6'd20) ? 2'd1 :
                       (animation_frame < 6'd40) ? 2'd2 : 2'd3;

always @* begin
    status_x = (frame_mode == 2'd1) ? 10'd176 : 10'd128;
    status_length = (frame_mode == 2'd1) ? 5'd9 : 5'd12;
    text_line = 3'd0;
    text_column = 5'd0;
    glyph_row = 5'd0;
    glyph_bit = 5'd0;
    text_enable = 1'b0;
    text_x_offset = 10'd0;
    selected_glyph = 6'd0;
    footer_glyph = 5'd0;
    font_address = 11'd0;
    if (de && (pixel_y >= 10'd272) && (pixel_y < 10'd304) &&
        (pixel_x >= 10'd256) && (pixel_x < 10'd384)) begin
        text_line = 3'd0;
        text_x_offset = pixel_x - 10'd256;
        text_column = text_x_offset[9:5];
        glyph_bit = text_x_offset[4:0];
        glyph_row = pixel_y - 10'd272;
        text_enable = 1'b1;
    end else if (de && (pixel_y >= 10'd336) && (pixel_y < 10'd368) &&
                 (pixel_x >= status_x) && (pixel_x < status_x + (status_length << 5))) begin
        text_line = {1'b0, frame_mode};
        text_x_offset = pixel_x - status_x;
        text_column = text_x_offset[9:5];
        glyph_bit = text_x_offset[4:0];
        glyph_row = pixel_y - 10'd336;
        text_enable = text_column < status_length - 5'd3 + dot_count;
    end else if (de && (pixel_y >= 10'd414) && (pixel_y < 10'd430) &&
                 (pixel_x >= 10'd232) && (pixel_x < 10'd408)) begin
        text_line = 3'd4;
        text_x_offset = pixel_x - 10'd232;
        text_column = text_x_offset[8:4];
        glyph_bit = {1'b0,text_x_offset[3:0]};
        glyph_row = pixel_y - 10'd414;
        text_enable = 1'b1;
    end
    selected_glyph = text_glyph(text_line, text_column);
    if ((text_line == 3'd4) && (text_column == 5'd10))
        selected_glyph = hexadecimal_glyph(frame_state);
    if (text_line == 3'd4) begin
        footer_glyph = selected_glyph == 6'd0 ? 5'd0 : selected_glyph - 6'd20;
        font_address = 11'd1344 + {2'd0,footer_glyph,glyph_row[3:2],glyph_bit[3:2]};
    end else
        font_address = {selected_glyph[4:0],glyph_row[4:2],glyph_bit[4:2]};
end

reg [8:0] logo_tile_id;
reg [7:0] font_tile_id_lo;
reg [1:0] font_tile_id_hi;
reg [47:0] logo_word;
reg [31:0] font_word;
reg [3:0] logo_pixel_d1, logo_pixel_d2, font_pixel_d1, font_pixel_d2;
reg [1:0] logo_region_pipe, text_enable_pipe, accent_pipe;
reg [2:0] text_line_d1, text_line_d2;
reg [1:0] mode_d1, mode_d2;
reg vs_d1, de_d1;
reg [23:0] source_rgb_d1, source_rgb_d2;

// Two synchronous ROM levels. Only immutable display assets use these memories.
always @(posedge clk) begin
    logo_tile_id <= logo_map[logo_address];
    font_tile_id_lo <= font_map_lo[font_address];
    font_tile_id_hi <= font_map_hi[font_address];
    logo_word <= logo_tiles[logo_tile_id];
    font_word <= font_tiles[{font_tile_id_hi,font_tile_id_lo}];
end
always @(posedge clk or posedge rst) begin
    if (rst) begin
        vs_d1 <= 1'b1; de_d1 <= 1'b0; out_vs <= 1'b1; out_de <= 1'b0;
        source_rgb_d1 <= 24'd0; source_rgb_d2 <= 24'd0;
        logo_pixel_d1 <= 4'd0; logo_pixel_d2 <= 4'd0;
        font_pixel_d1 <= 4'd0; font_pixel_d2 <= 4'd0;
        logo_region_pipe <= 2'd0; text_enable_pipe <= 2'd0; accent_pipe <= 2'd0;
        text_line_d1 <= 3'd0; text_line_d2 <= 3'd0;
        mode_d1 <= 2'd1; mode_d2 <= 2'd1;
    end else begin
        vs_d1 <= vs; de_d1 <= de; out_vs <= vs_d1; out_de <= de_d1;
        source_rgb_d1 <= source_rgb; source_rgb_d2 <= source_rgb_d1;
        logo_pixel_d1 <= {logo_y_offset[1:0],logo_x_offset[1:0]};
        logo_pixel_d2 <= logo_pixel_d1;
        font_pixel_d1 <= {glyph_row[1:0],glyph_bit[1:0]};
        font_pixel_d2 <= font_pixel_d1;
        logo_region_pipe <= {logo_region_pipe[0],logo_region};
        text_enable_pipe <= {text_enable_pipe[0],text_enable};
        accent_pipe <= {accent_pipe[0],de && (pixel_x >= 10'd64) &&
                       (pixel_x < 10'd576) && (pixel_y >= 10'd98) && (pixel_y < 10'd100)};
        text_line_d1 <= text_line; text_line_d2 <= text_line_d1;
        mode_d1 <= frame_mode; mode_d2 <= mode_d1;
    end
end

function [23:0] logo_palette;
    input [2:0] color;
    begin
        case (color)
        3'd0: logo_palette = 24'hffffff;
        3'd1: logo_palette = 24'hb4b9c3;
        3'd2: logo_palette = 24'h697287;
        3'd3: logo_palette = 24'h1e2c4b;
        3'd4: logo_palette = 24'hf8b3b9;
        3'd5: logo_palette = 24'hf06773;
        3'd6: logo_palette = 24'he91b2d;
        3'd7: logo_palette = 24'hffffff;
            default: logo_palette = 24'hffffff;
        endcase
    end
endfunction
function [23:0] font_palette;
    input title;
    input [1:0] alpha;
    begin
        case ({title,alpha})
        3'd0: font_palette = 24'hffffff;
        3'd1: font_palette = 24'hc7cbd3;
        3'd2: font_palette = 24'h8f98a6;
        3'd3: font_palette = 24'h57647a;
        3'd4: font_palette = 24'hffffff;
        3'd5: font_palette = 24'hb4b9c3;
        3'd6: font_palette = 24'h697287;
        3'd7: font_palette = 24'h1e2c4b;
            default: font_palette = 24'hffffff;
        endcase
    end
endfunction
wire [5:0] logo_shift = {logo_pixel_d2,1'b0} + {2'b0,logo_pixel_d2};
wire [2:0] logo_color = (logo_word >> logo_shift) & 3'b111;
wire [1:0] font_alpha = (font_word >> {font_pixel_d2,1'b0}) & 2'b11;
always @* begin
    out_rgb = source_rgb_d2;
    if (mode_d2 != 2'd0) begin
        out_rgb = 24'hffffff;
        if (accent_pipe[1]) out_rgb = 24'he91b2d;
        if (logo_region_pipe[1]) out_rgb = logo_palette(logo_color);
        if (text_enable_pipe[1] && font_alpha != 2'd0)
            out_rgb = font_palette(text_line_d2 == 3'd0,font_alpha);
    end
    if (!out_de) out_rgb = 24'd0;
end
endmodule
